import csv
import json
import math
from pathlib import Path
root = Path('code/V4/runs/R68_sharpness_aware_finetuning')
cache = {}
def read(path):
    key = str(path)
    if key not in cache:
        cache[key] = json.loads(Path(path).read_text())
    return cache[key]
def pointer(path, location):
    value = read(path)
    for key in location.strip('/').split('/') if location else []:
        value = value[key]
    return value
provenance = read(root/'reference_provenance.json')['references']
arm_names = {'R68A':'A_plain_adamw_seed2', 'R68B':'B_sam_adamw_seed2'}
def record(model, split):
    if model in arm_names:
        if split == 'test':
            return read(root/'test_results.json')['models'][model[-1]]
        return read(root/arm_names[model]/'result.json')['best'][split]
    source = provenance[model]
    if 'original_provenance' in source:
        if split == 'train':
            entry = source['train_source']
        else:
            entry = source['original_provenance']['validation' if split == 'val' else 'test']
        return pointer(entry['path'], entry['json_pointer'])
    return pointer(source['test_path'] if split == 'test' else source['result_path'],
                   source[{'train':'train_json_pointer','val':'validation_json_pointer','test':'test_json_pointer'}[split]])
metrics = ('top1','top2','top3','ce','mean_cost','actual_regret_pct','vs_sbs_pct')
rows = list(csv.DictReader((root/'comparison.csv').open()))
errors = []
for index, row in enumerate(rows, 2):
    saved = record(row['model'], row['split'])
    if row['kind'] == 'aggregate':
        values = {key:saved['macro']['macro_'+key] for key in metrics}
    elif row['kind'] == 'task':
        values = saved['per_problem'][row['scope']]
    elif 'families' in saved:
        values = {key:saved['families'][row['scope']]['macro_'+key] for key in metrics}
    else:
        entries = [value for task,value in saved['per_problem'].items()
                   if (task not in ('TSP','CVRP','ATSP') if row['scope']=='MVRP' else task==row['scope'])]
        values = {key:sum(value[key] for value in entries)/len(entries) for key in metrics}
    for key in metrics:
        if not math.isclose(float(row[key]), values[key], rel_tol=1e-12, abs_tol=1e-12):
            errors.append({'line':index,'model':row['model'],'split':row['split'],'scope':row['scope'],'metric':key,'csv':row[key],'saved':values[key]})
print(json.dumps({'saved_summary_rows_compared':len(rows),'metric_values_compared':len(rows)*len(metrics),'mismatches':errors,'source':'saved JSON summaries only; no model imports or NPZ access'}))
PY"

